_TO01 = bytes.maketrans(b"01", b"\x00\x01")
_PAR = bytes((b & 1) + 48 for b in range(256))

def spread(a):
    return int.from_bytes(format(a, "0128b").encode().translate(_TO01), "big")

def clmul2(a, b):
